function bookingDetails(id){const b=salon().bookings.find(x=>x.id===id);if(!b)return;modal('Appointment details',`<div class="row between"><h3>${esc(b.name)}</h3>${statusPill(b.status)}</div><div class="key-value"><span>Service</span><b>${esc(b.serviceName)}</b></div><div class="key-value"><span>Professional</span><b>${esc(staffName(b.staffId))}</b></div><div class="key-value"><span>Time</span><b>${humanDate(b.date)} · ${b.time} (${b.duration} min)</b></div><div class="key-value"><span>Contact</span><b>${esc(b.email)}<br>${esc(b.phone)}</b></div><div class="key-value"><span>Price / deposit</span><b>${money(b.price)} / ${money(b.deposit)}</b></div>${b.notes?`<div class="key-value"><span>Notes</span><b>${esc(b.notes)}</b></div>`:''}<div class="row section-space">${b.status==='confirmed'?`<button class="btn primary" data-action="edit-booking" data-id="${id}">Edit</button><button data-action="reschedule" data-id="${id}">Reschedule</button><button data-action="complete-booking" data-id="${id}">Mark completed</button><button class="danger" data-action="cancel-booking" data-id="${id}">Cancel</button>`:`<button class="btn primary" data-action="edit-booking" data-id="${id}">Edit</button>`}<button class="danger" data-action="delete-booking" data-id="${id}">Delete</button><a class="btn" href="#manage/${id}" data-action="close-modal">Customer manage page</a></div>`);}
