function refreshEdit(f,name){const s=salon(),b=s.bookings.find(x=>x.id===f.dataset.id);if(!b)return;const svc=s.services.find(x=>x.id===f.elements['serviceId'].value);if(!svc)return;if(name==='serviceId'){const el=eligible(s,svc),sel=f.elements['staffId'],cur=sel.value;sel.innerHTML=staffOpts(el,el.some(m=>m.id===cur)?cur:el[0]?.id,false);}const staffId=f.elements['staffId'].value,date=f.elements['date'].value;let ts=available(date,svc.id,b.id,staffId);if(b.date===date&&b.serviceId===svc.id&&b.staffId===staffId&&!ts.includes(b.time))ts=[...ts,b.time].sort();const cur=f.elements['time'].value;f.elements['time'].innerHTML=ts.map(t=>`<option ${t===cur?'selected':''}>${t}</option>`).join('')||'<option value="">No available times</option>';}
