function customerHistory(id){const s=salon(),c=s.customers.find(x=>x.id===id);if(!c)return;modal('Customer history',`<div class="row between"><div><h3 style="margin:0">${esc(c.name)}</h3><p style="margin:4px 0 0">${esc(c.email)}<br>${esc(c.phone)||'No phone'}</p></div><div class="row"><button class="small" data-action="edit-customer" data-id="${id}">Edit</button><button class="small danger" data-action="delete-customer" data-id="${id}">Delete</button></div></div>${c.notes?`<div class="notice section-space">${esc(c.notes)}</div>`:''}<div class="section-space">${bookingTable(s.bookings.filter(b=>b.customerId===id).sort(sortBookings))}</div>`,'large');}
function staffForm(id){const s=salon(),m=s.staff.find(x=>x.id===id)||{name:'',role:'',active:true,hours:null},custom=!!m.hours,h=m.hours||s.hours;modal(id?'Edit staff member':'Add staff member',`<form data-form="staff" data-id="${id||''}">${field('Name','name',m.name,'text','required maxlength="80"')}${field('Role (optional)','role',m.role||'','text','maxlength="60" placeholder="e.g. Stylist"')}<label class="check"><input type="checkbox" name="active" ${m.active?'checked':''}> Bookable online</label><label class="check"><input type="checkbox" name="follow" id="staff-follow" ${custom?'':'checked'}> Works the salon’s opening hours (${s.hours.start}–${s.hours.end})</label><div id="staff-hours" ${custom?'':'hidden'}><div class="grid two">${field('Starts','start',h.start,'time','required')}${field('Ends','end',h.end,'time','required')}</div><label class="field">Working days</label>${dayChecks(h.days)}</div><label class="field section-space">Services this person offers</label><div class="checklist">${s.services.map(x=>`<label class="check"><input type="checkbox" name="svc" value="${x.id}" ${(id?(x.staffIds||[]).includes(id):true)?'checked':''}> ${esc(x.name)}</label>`).join('')||'<p class="tiny">Add services first.</p>'}</div><div class="error" role="alert"></div><button class="btn primary">${id?'Save changes':'Add staff member'}</button></form>`);}
function handleCrud(a,id,el,s){
 if(a==='cal-view'){calView=el.dataset.value;render();return true;}
 if(a==='cal-goto'){calendarWeek=el.dataset.date;calView='day';render();return true;}
 if(a==='staff-calendar'){calStaff=id;calView='week';calendarWeek=today();go('calendar');return true;}
 if(a==='add-customer'){customerForm();return true;}
 if(a==='edit-customer'){customerForm(id);return true;}
 if(a==='delete-customer'){const c=s.customers.find(x=>x.id===id);if(!c)return true;modal('Delete this customer?',`<p><b>${esc(c.name)}</b> will be removed from your customer list. Their past appointments stay in your diary under their name. This cannot be undone.</p><div class="row"><button class="danger" data-action="delete-customer-confirm" data-id="${id}">Delete customer</button><button data-action="close-modal">Keep customer</button></div>`);return true;}
 if(a==='delete-customer-confirm'){const up=s.bookings.filter(b=>b.customerId===id&&b.status==='confirmed'&&b.date>=today()).length;if(up){closeModal();toast(`This customer has ${up} upcoming appointment${up>1?'s':''}. Cancel or move them first.`);return true;}s.customers=s.customers.filter(x=>x.id!==id);save();closeModal();render();toast('Customer deleted.');return true;}
 if(a==='add-category'){categoryForm();return true;}
 if(a==='edit-category'){categoryForm(id);return true;}
 if(a==='delete-category'){const c=s.categories.find(x=>x.id===id);if(!c)return true;const n=s.services.filter(x=>x.categoryId===id).length;modal('Delete this category?',`<p><b>${esc(c.name)}</b> will be removed.${n?` Its ${n} service${n>1?'s':''} will stay on your menu without a category.`:''}</p><div class="row"><button class="danger" data-action="delete-category-confirm" data-id="${id}">Delete category</button><button data-action="close-modal">Keep category</button></div>`);return true;}
 if(a==='delete-category-confirm'){s.categories=s.categories.filter(x=>x.id!==id);s.services.forEach(x=>{if(x.categoryId===id)x.categoryId='';});save();closeModal();render();toast('Category deleted.');return true;}
 if(a==='add-staff'){staffForm();return true;}
 if(a==='edit-staff'){staffForm(id);return true;}
 if(a==='delete-staff'){const m=s.staff.find(x=>x.id===id);if(!m)return true;modal('Delete this staff member?',`<p><b>${esc(m.name)}</b> will be removed from your team and from every service. Past appointments stay in your diary. This cannot be undone.</p><div class="row"><button class="danger" data-action="delete-staff-confirm" data-id="${id}">Delete staff member</button><button data-action="close-modal">Keep</button></div>`);return true;}
 if(a==='delete-staff-confirm'){const m=s.staff.find(x=>x.id===id);if(!m)return true;if(s.staff.length<=1){closeModal();toast('A salon needs at least one staff member.');return true;}const up=s.bookings.filter(b=>b.staffId===id&&b.status==='confirmed'&&b.date>=today()).length;if(up){closeModal();toast(`${m.name} has ${up} upcoming appointment${up>1?'s':''}. Cancel or move them first.`);return true;}s.staff=s.staff.filter(x=>x.id!==id);s.services.forEach(x=>{x.staffIds=(x.staffIds||[]).filter(i=>i!==id);});if(calStaff===id)calStaff='all';save();closeModal();render();toast('Staff member deleted.');return true;}
 if(a==='edit-booking'){editBooking(id);return true;}
 if(a==='delete-booking'){const b=s.bookings.find(x=>x.id===id);if(!b)return true;modal('Delete this appointment?',`<p>${esc(b.name)} · ${esc(b.serviceName)}<br>${humanDate(b.date)} at ${b.time}</p><p>This removes the appointment completely and no cancellation email is sent. To tell the customer, use <b>Cancel</b> instead. Deleting cannot be undone.</p><div class="row"><button class="danger" data-action="delete-booking-confirm" data-id="${id}">Delete appointment</button><button data-action="close-modal">Keep appointment</button></div>`);return true;}
 if(a==='delete-booking-confirm'){s.bookings=s.bookings.filter(x=>x.id!==id);save();closeModal();render();toast('Appointment deleted.');return true;}
 return false;}
function handleForms(type,form,data,s){
 if(type==='customer'){const id=form.dataset.id,name=data.name.trim(),email=data.email.trim();if(!name||!email)throw Error('Add a name and an email.');if(s.customers.some(c=>c.id!==id&&c.email.toLowerCase()===email.toLowerCase()))throw Error('Another customer already uses that email.');const phone=data.phone.trim(),notes=(data.notes||'').trim();if(id){const c=s.customers.find(x=>x.id===id);Object.assign(c,{name,email,phone,notes});s.bookings.filter(b=>b.customerId===id).forEach(b=>Object.assign(b,{name,email,phone}));}else s.customers.push({id:uid('c'),name,email,phone,notes});save();closeModal();render();toast(id?'Customer saved.':'Customer added.');return true;}
 if(type==='category'){const id=form.dataset.id,name=data.name.trim();if(!name)throw Error('Enter a category name.');if(s.categories.some(c=>c.id!==id&&c.name.toLowerCase()===name.toLowerCase()))throw Error('That category already exists.');if(id)s.categories.find(c=>c.id===id).name=name;else s.categories.push({id:uid('cat'),name});save();closeModal();render();toast(id?'Category saved.':'Category added.');return true;}
 if(type==='service'){const id=form.dataset.id,fd=new FormData(form),old=s.services.find(x=>x.id===id),x={name:data.name.trim(),price:Number(data.price),duration:Number(data.duration),categoryId:data.categoryId||'',staffIds:fd.getAll('staffIds')};if(!x.name)throw Error('Enter a service name.');if(!Number.isFinite(x.price)||x.price<0||x.price>10000)throw Error('Enter a price of £0 or more.');if(!Number.isFinite(x.duration)||x.duration<5||x.duration>600)throw Error('Duration must be between 5 and 600 minutes.');if(!x.staffIds.length)throw Error('Choose at least one person who offers this service.');if(old)Object.assign(old,x);else s.services.push({id:uid('svc'),...x});save();closeModal();render();toast('Service saved.');return true;}
 if(type==='staff'){const id=form.dataset.id,fd=new FormData(form),name=data.name.trim();if(!name)throw Error('Enter a name.');let hours=null;if(!fd.get('follow')){const sel=fd.getAll('days').map(Number);if(!sel.length)throw Error('Choose at least one working day.');if(mins(data.start)>=mins(data.end))throw Error('End time must be later than start time.');hours={start:data.start,end:data.end,days:sel};}let m=s.staff.find(x=>x.id===id);const fields={name,role:data.role.trim(),active:!!fd.get('active'),hours};if(m)Object.assign(m,fields);else{m={id:uid('st'),color:STAFF_COLORS[s.staff.length%STAFF_COLORS.length],...fields};s.staff.push(m);}const chosen=fd.getAll('svc');s.services.forEach(x=>{x.staffIds=(x.staffIds||[]).filter(i=>i!==m.id);if(chosen.includes(x.id))x.staffIds.push(m.id);});save();closeModal();render();toast(id?'Staff member saved.':'Staff member added.');return true;}
 if(type==='edit-booking'){const b=s.bookings.find(x=>x.id===form.dataset.id);if(!b)throw Error('Appointment not found.');const svc=s.services.find(x=>x.id===data.serviceId),same=b.serviceId===data.serviceId;if(!svc&&!same)throw Error('Choose a valid service.');const sameSlot=same&&b.staffId===data.staffId&&b.date===data.date&&b.time===data.time;if(!sameSlot){const ts=svc?available(data.date,svc.id,b.id,data.staffId):[];if(!ts.includes(data.time))throw Error('That time is not free for this person. Choose another.');}const moved=b.date!==data.date||b.time!==data.time;if(svc&&!same)Object.assign(b,{serviceId:svc.id,serviceName:svc.name,duration:svc.duration,price:svc.price});Object.assign(b,{staffId:data.staffId,date:data.date,time:data.time,notes:(data.notes||'').trim()});if(moved&&b.status==='confirmed')notify('rescheduled',b);save();calendarWeek=b.date;closeModal();render();toast('Appointment updated.');return true;}
 return false;}
function createBooking(data,source='Online'){
 const s=salon(),svc=s.services.find(x=>x.id===data.serviceId);
 if(!svc)throw Error('Choose a valid service.');
 const m=pickStaff(data.date,data.time,data.serviceId,data.staffId||'any');if(!m)throw Error('That time is no longer available. Please choose another slot.');
 if(!data.name?.trim()||!data.email?.trim())throw Error('Add a customer name and email before confirming.');
 let c=s.customers.find(c=>c.email.toLowerCase()===data.email.toLowerCase());
 if(!c){c={id:uid('c'),name:data.name.trim(),email:data.email.trim(),phone:data.phone||''};s.customers.push(c);}
 const deposit=source==='Online'&&s.payments.enabled?Math.min(Number(s.payments.deposit),svc.price):0;
 const b={id:uid('bk'),serviceId:svc.id,serviceName:svc.name,duration:svc.duration,price:svc.price,date:data.date,time:data.time,staffId:m.id,notes:(data.notes||'').trim(),customerId:c.id,name:data.name.trim(),email:data.email.trim(),phone:data.phone||'',source,status:'confirmed',deposit};
 s.bookings.push(b);if(deposit>0){const fee=Math.round((deposit*.015+.2)*100)/100;s.payments.transactions.unshift({id:uid('pay'),bookingId:b.id,name:b.name,amount:deposit,fee,net:Math.round((deposit-fee)*100)/100,method:data.method||'Card'});}
 notify('confirmed',b);save();return b;
}
function reschedule(id,date=nextDate()){const b=salon().bookings.find(x=>x.id===id);if(!b||b.status!=='confirmed')return;const times=available(date,b.serviceId,id,b.staffId);modal('Reschedule appointment',`<p>${esc(b.name)} · ${esc(b.serviceName)}<br>Currently ${humanDate(b.date)} at ${b.time}</p><form data-form="reschedule" data-id="${id}">${field('New date','date',date,'date',`required min="${today()}"`)}<label class="field">Available time<select name="time" required>${times.map(t=>`<option value="${t}">${t}</option>`).join('')||'<option value="">No available times</option>'}</select></label><div class="error" role="alert"></div><button class="btn primary">Save new time</button></form>`);}
function emailPreview(id){const e=salon().emails.find(x=>x.id===id);if(!e)return;const b=e.booking;modal('Email preview',`<div class="email"><p class="tiny"><b>From:</b> ${esc(e.from)}<br><b>To:</b> ${esc(e.to)}<br><b>Reply-To:</b> ${esc(e.reply)}<br><b>Subject:</b> ${esc(e.subject)}</p><article><div class="brand" style="font-size:19px">jova<em>book</em></div><h2 class="section-space">${e.kind==='cancelled'?'Appointment cancelled':e.kind==='rescheduled'?'Your new appointment time':e.kind==='reminder'?'See you soon':'Your booking is confirmed'}</h2><p>Hello ${esc(b.name)},</p><p>${esc(b.serviceName)} at <b>${esc(e.salonName)}</b><br>${humanDate(b.date)} at ${b.time}<br>${esc(e.address)}</p><p>Total: ${money(b.price)}<br>Deposit paid: ${money(b.deposit)}</p><a class="btn primary small" href="#manage/${b.id}" data-action="close-modal">Manage appointment</a><p class="tiny section-space">Powered by Jova Media. This email was simulated locally and has not been sent.</p></article></div>`);}
function chatSend(text){chat.push({role:'user',text});const s=salon();const svc=s.services.find(x=>text.toLowerCase().includes(x.name.toLowerCase())||x.name.toLowerCase().split(' ').some(w=>w.length>3&&text.toLowerCase().includes(w.replace(/s$/,''))));let reply;if(svc){draft={...defaultDraft(),serviceId:svc.id};const times=available(draft.date,svc.id);reply=`${svc.name} is ${money(svc.price)} and takes ${svc.duration} minutes. On ${humanDate(draft.date)}, the demo diary has ${times.slice(0,3).join(', ')||'no available slots'}. Choose “Continue to available times” to select a slot and confirm your details. I haven't booked anything yet.`;}else if(/price|cost|service|treatment|available|book/i.test(text))reply=`Our demo services are ${s.services.map(x=>x.name+' ('+money(x.price)+')').join(', ')}. Which would you like?`;else reply='This is a scripted preview, so I can help with the listed treatments only. Choose a treatment below, or use the booking page. An unsupported request would go to the salon in the real product.';chat.push({role:'assistant',text:reply});render();}
